import fs from 'node:fs';import vm from 'node:vm';import assert from 'node:assert/strict';import {createHash} from 'node:crypto';import {Renderer as LinkedRenderer,lightingAt,fixtureLightLevel} from '../src/render.js';import {BUILD as LinkedBuild,idleWeaponHeading as linkedIdleWeaponHeading} from '../src/core.js';import {matchBrowserLanguage,translateText} from '../src/i18n.js';
